{
  "schema": "proof.liskov.application-manifest",
  "schemaVersion": 4,
  "applicationId": "golden-fixture",
  "applicationUid": "app-00000000000000000000000000000001",
  "metadata": {
    "description": "canonical V4 golden fixture"
  },
  "release": {
    "mode": "pinned",
    "artifact": {
      "kind": "ipfs_bundle",
      "cid": "ipfs://QmGoldenFixtureCidV4Contract0000000000000001",
      "digest": "sha256:aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa",
      "encryption": {
        "mode": "none"
      }
    }
  },
  "runtime": {
    "command": "node index.js"
  },
  "deployment": {
    "parallelism": 1,
    "schedule": {
      "durationMs": 1800000
    },
    "lifecycle": {
      "renewal": {
        "mode": "after_scheduled_end"
      },
      "update": {
        "timing": "immediate",
        "existingJobs": {
          "mode": "run_until_scheduled_end"
        }
      },
      "recovery": {
        "launch": {
          "maxRetries": 0
        },
        "runtimeFailure": {
          "mode": "wait_until_scheduled_end"
        }
      }
    }
  },
  "observability": {
    "logs": {
      "enabled": true,
      "sinkName": "golden-fixture",
      "context": {
        "component": "golden"
      }
    },
    "runtimeDiagnostics": {
      "signed": true
    }
  }
}

# EXPECT: is claimed by
# EXPECT-CODE: invalid_manifest
# EXPECT-POINTER: /configuration
# A variable and a secret destination cannot claim the same environment name.
schema: proof.liskov.application-manifest
schemaVersion: 5
applicationId: bad-collision
release: {mode: source}
runtime: {kind: javascript, entrypoint: {file: app.js}}
execution: {mode: once}
deployment:
  schedule: {duration: 1h}
  spend: {unit: service_credit_micros, perJob: "1"}
configuration:
  variables:
    - {name: API_KEY, source: literal, value: x}
  secrets:
    - secretId: api-key
      destination: {kind: environment, name: API_KEY}

state:
  mode: off

# EXPECT: matched no variant of the union
# EXPECT-CODE: invalid_manifest
# EXPECT-POINTER: /deployment/placement/processorSelection/mode
# ADR-0074 makes manager identity a hard allow/exclude filter. It is not a
# processor source; only exact processor IDs remain under processorSelection.
schema: proof.liskov.application-manifest
schemaVersion: 5
applicationId: bad-manager-selection
release: {mode: source}
runtime: {kind: javascript, entrypoint: {file: app.js}}
execution: {mode: once}
deployment:
  schedule: {duration: 1h}
  placement:
    processorSelection: {mode: manager, managerId: "42"}
  spend: {unit: service_credit_micros, perJob: "1"}

state:
  mode: off

# EXPECT: unknown property 'evidence'
# EXPECT-CODE: invalid_manifest
# EXPECT-POINTER: /deployment/placement/evidence
# ADR-0076 makes processor intelligence mandatory platform behavior. Customers
# cannot select, relax, or disable the internal evidence profile.
schema: proof.liskov.application-manifest
schemaVersion: 5
applicationId: bad-placement-evidence
release: {mode: source}
runtime: {kind: javascript, entrypoint: {file: app.js}}
execution: {mode: once}
deployment:
  schedule: {duration: 1h}
  placement:
    evidence: {profile: proof.liskov.recent-placement.v1}
  spend: {unit: service_credit_micros, perJob: "1"}
state:
  mode: off

# EXPECT: valid only for continuous execution
# EXPECT-CODE: invalid_manifest
# EXPECT-POINTER: /deployment/lifecycle/renewal
# Renewal must not define once or interval cadence.
schema: proof.liskov.application-manifest
schemaVersion: 5
applicationId: bad-renewal
release: {mode: source}
runtime: {kind: javascript, entrypoint: {file: app.js}}
execution: {mode: once}
deployment:
  schedule: {duration: 1h}
  lifecycle:
    renewal: {leadTime: {mode: automatic}}
  spend: {unit: service_credit_micros, perJob: "1"}

state:
  mode: off

# EXPECT: unknown property 'recovery'
# EXPECT-CODE: invalid_manifest
# EXPECT-POINTER: /deployment/recovery
# ADR-0050 deletes the retry/replace/generation budget vocabulary. maxRetries: 0
# turning a processor hiccup into a park is the exact foot-gun it removes.
schema: proof.liskov.application-manifest
schemaVersion: 5
applicationId: bad-recovery
release: {mode: source}
runtime: {kind: javascript, entrypoint: {file: app.js}}
execution: {mode: continuous}
deployment:
  schedule: {duration: 1h}
  lifecycle:
    recovery: {launch: {maxRetries: 0}}
  spend: {unit: service_credit_micros, perJob: "1", rate: {amount: "1"}}

state:
  mode: off

# EXPECT: does not match
# EXPECT-CODE: invalid_manifest
# EXPECT-POINTER: /deployment/schedule/duration
# One unit-bearing duration grammar. Millisecond integers are not authored.
schema: proof.liskov.application-manifest
schemaVersion: 5
applicationId: bad-duration
release: {mode: source}
runtime: {kind: javascript, entrypoint: {file: app.js}}
execution: {mode: once}
deployment:
  schedule: {duration: "900000"}
  spend: {unit: service_credit_micros, perJob: "1"}

state:
  mode: off

# EXPECT: unknown property 'maxGenerations'
# EXPECT-CODE: invalid_manifest
# EXPECT-POINTER: /deployment/maxGenerations
# runtime.maxGenerations is not a V5 customer concept — it moved to `execution`.
schema: proof.liskov.application-manifest
schemaVersion: 5
applicationId: bad-unknown
release: {mode: source}
runtime: {kind: javascript, entrypoint: {file: app.js}, maxGenerations: 1}
execution: {mode: once}
deployment:
  schedule: {duration: 1h}
  spend: {unit: service_credit_micros, perJob: "1"}

state:
  mode: off
